examples.css:
p { color: red; }
.text { color: green; }
p.text { color: blue; }
#msg { color: orange; }
/* answer: orange (id beats class and element) */

.a { margin-bottom: 30px; background: #fde68a; }
.b { margin-top: 50px; background: #bfdbfe; }
/* gap between A and B? 50px, not 80px (margin collapse) */

.row { display: flex; width: 280px; border: 2px solid #94a3b8; font-family: sans-serif; }
.long { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; background: #dbeafe; }
.side { flex: 0 0 60px; background: #fde68a; text-align: center; }
/* remove min-width: 0 to see the overflow bug */
